INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", 2.15, 2, 1, -470.0, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 0.0, 2, 126401, "2023/09/22 14:59:59", 2002, 10002, "クローチェ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", 0.0, 1, 1, -470.0, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2, 0.0, 2, 126501, "2023/09/22 14:59:59", 2002, 10003, "ライラエル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/06/30 12:00:00", 0.0, 2, 1, -470.0, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 0.0, 1, 126501, "2023/09/22 14:59:59", 2002, 10004, "ライラエル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", 0.0, 1, 2, -470.0, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 0.0, 2, 127702, "2023/12/22 14:59:59", 2002, 10005, "リンド");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", 0.0, 2, 2, -470.0, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 0.0, 2, 127702, "2023/12/22 14:59:59", 2002, 10006, "リンド");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", 0.0, 1, 2, -470.0, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 1, 0.0, 1, 127802, "2023/12/22 14:59:59", 2002, 10007, "ヴルム");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/15 15:00:00", 6.5, 2, 2, -470.0, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 1, 0.0, 2, 127802, "2023/12/22 14:59:59", 2002, 10008, "ヴルム");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", 0.0, 1, 3, -470.0, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 1, 0.0, 2, 129602, "2024/03/22 14:59:59", 2002, 10009, "アネモネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", 0.0, 2, 3, -470.0, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 1, 0.0, 2, 129602, "2024/03/22 14:59:59", 2002, 10010, "アネモネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", 0.0, 1, 3, -470.0, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 1, 0.0, 1, 129701, "2024/03/22 14:59:59", 2002, 10011, "ネフィ=ネラ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/15 15:00:00", 6.2, 2, 3, -470.0, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 1, 0.0, 2, 129701, "2024/03/22 14:59:59", 2002, 10012, "ネフィ=ネラ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", 3.1, 1, 4, -470.0, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 5, 0.0, 3, 130301, "2024/06/22 14:59:59", 2002, 10013, "カノン");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", 6.15, 2, 4, -470.0, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2, 0.0, 3, 130301, "2024/06/22 14:59:59", 2002, 10014, "カノン");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", 0.0, 1, 4, -470.0, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2, 0.0, 2, 130401, "2024/06/22 14:59:59", 2002, 10015, "ナーナ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/15 15:00:00", 3.35, 2, 4, -470.0, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 1, 0.0, 2, 130401, "2024/06/22 14:59:59", 2002, 10016, "ナーナ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", 0.0, 1, 5, -470.0, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 1, 0.0, 1, 130502, "2024/09/22 14:59:59", 2002, 10017, "ホウオウ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", 3.18, 2, 5, -470.0, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 1, 0.0, 2, 130502, "2024/09/22 14:59:59", 2002, 10018, "ホウオウ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", 0.0, 3, 5, -470.0, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 4, 0.0, 4, 130503, "2024/09/22 14:59:59", 2002, 10019, "ホウオウ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", 4.9, 1, 5, -470.0, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2, 0.0, 1, 123301, "2024/09/22 14:59:59", 2002, 10020, "ネア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/15 15:00:00", 4.8, 2, 5, -470.0, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2, 0.0, 1, 123301, "2024/09/22 14:59:59", 2002, 10021, "ネア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", 4.922, 1, 6, -470.0, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 1, 0.0, 3, 133301, "2024/12/22 14:59:59", 2002, 10022, "カリザ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", 9.638, 2, 6, -470.0, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 5, 0.0, 3, 133301, "2024/12/22 14:59:59", 2002, 10023, "カリザ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", 2.88, 1, 6, -470.0, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2, 0.0, 1, 133401, "2024/12/22 14:59:59", 2002, 10024, "ミーア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/15 15:00:00", 4.818, 2, 6, -470.0, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 1, 0.0, 5, 133401, "2024/12/22 14:59:59", 2002, 10025, "ミーア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", 1.78, 1, 7, -470.0, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 1, 0.0, 2, 133002, "2025/03/22 14:59:59", 2002, 10026, "グレイス");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", 6.15, 2, 7, -470.0, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 0.0, 1, 133002, "2025/03/22 14:59:59", 2002, 10027, "グレイス");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", 4.28, 1, 7, -470.0, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2, 0.0, 6, 133102, "2025/03/22 14:59:59", 2002, 10028, "ヴァイオレット");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/15 15:00:00", 0.0, 2, 7, -470.0, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 1, 0.0, 1, 133102, "2025/03/22 14:59:59", 2002, 10029, "ヴァイオレット");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", 5.53, 1, 8, -470.0, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 1, 0.0, 2, 136902, "2025/06/23 14:59:59", 2002, 10030, "ルルィ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", 6.05, 2, 8, -470.0, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 7, 0.0, 9, 136902, "2025/06/23 14:59:59", 2002, 10031, "ルルィ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", 0.0, 1, 8, -470.0, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 1, 0.0, 2, 137001, "2025/06/23 14:59:59", 2002, 10032, "デュラン");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/15 15:00:00", 0.0, 2, 8, -470.0, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 1, 0.0, 2, 137001, "2025/06/23 14:59:59", 2002, 10033, "デュラン");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", 0.0, 1, 9, -470.0, "おう\n好きなもん持ってきな", 2, 0.0, 2, 135902, "2025/09/23 14:59:59", 2002, 10034, "サツキ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", 4.935, 2, 9, -470.0, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 6, 0.0, 1, 135902, "2025/09/23 14:59:59", 2002, 10035, "サツキ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", 7.441, 1, 9, -470.0, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 5, 0.0, 2, 135802, "2025/09/23 14:59:59", 2002, 10036, "ユキノ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/16 15:00:00", 0.0, 2, 9, -470.0, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 7, 0.0, 7, 135802, "2025/09/23 14:59:59", 2002, 10037, "ユキノ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", 2.295, 1, 10, -470.0, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2, 0.0, 2, 130901, "2025/12/22 14:59:59", 2002, 10038, "クルル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", 6.281, 2, 10, -470.0, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 6, 0.0, 1, 130901, "2025/12/22 14:59:59", 2002, 10039, "クルル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", 5.549, 1, 10, -470.0, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 1, 0.0, 2, 137701, "2025/12/22 14:59:59", 2002, 10040, "ヴォルガーノ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/16 15:00:00", 2.64, 2, 10, -470.0, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 6, 0.0, 3, 137701, "2025/12/22 14:59:59", 2002, 10041, "ヴォルガーノ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", 7.642, 1, 11, -470.0, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 4, 0.0, 7, 132801, "2026/03/23 11:59:59", 2002, 10042, "ライラエル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", 0.0, 2, 11, -470.0, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 1, 0.0, 1, 132802, "2026/03/23 11:59:59", 2002, 10043, "ライラエル");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", 0.0, 1, 11, -470.0, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 1, 0.0, 1, 134502, "2026/03/23 11:59:59", 2002, 10044, "クローチェ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/15 15:00:00", 3.72, 2, 11, -470.0, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 1, 0.0, 2, 134501, "2026/03/23 11:59:59", 2002, 10045, "クローチェ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", 4.991, 1, 12, -470.0, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 1, 0.0, 2, 138201, "2026/06/22 11:59:59", 2002, 10046, "ネフィ＝ネラ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", 3.877, 2, 12, -470.0, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 4, 0.0, 1, 138201, "2026/06/22 11:59:59", 2002, 10047, "ネフィ＝ネラ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", 1.71, 1, 12, -470.0, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 6, 0.0, 4, 136001, "2026/06/22 11:59:59", 2002, 10048, "アラクネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/16 12:00:00", 5.32, 2, 12, -470.0, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2, 0.0, 5, 136001, "2026/06/22 11:59:59", 2002, 10049, "アラクネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", 3.727, 1, 13, -470.0, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 4, 0.0, 9, 135401, "2026/09/22 11:59:59", 2002, 10050, "アネモネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", 7.213, 2, 13, -470.0, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 9, 0.0, 7, 135401, "2026/09/22 11:59:59", 2002, 10051, "アネモネ");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", 1.874, 1, 13, -470.0, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2, 0.0, 1, 135301, "2026/09/22 11:59:59", 2002, 10052, "クリア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/15 12:00:00", 0.0, 2, 13, -470.0, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2, 0.0, 2, 135301, "2026/09/22 11:59:59", 2002, 10053, "クリア");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/15 12:00:00", 4.215, 1, 14, -470.0, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 1, 0.0, 2, 138001, "2026/12/22 11:59:59", 2002, 10054, "ヴァイオレット");
